@CrossOrigin
@RestController
@RequestMapping("/QuarantineQuery")
public class QuarantineQueryRestController extends BaseSpringRestController {
	
	public QuarantineQueryRestController( QuarantineService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Quarantine using a UUID
     * @param		UUID quarantineId
     * @return		Quarantine
     */    
    @GetMapping("/load")
    public Quarantine load( @RequestParam(required=true) UUID quarantineId ) {
    	Quarantine entity = null;

    	try {  
    		entity = service.getQuarantine( new QuarantineFetchOneSummary( quarantineId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Quarantine using Id " + quarantineId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Quarantine business objects
     * @return		Set<Quarantine>
     */
    @GetMapping("/")
    public List<Quarantine> loadAll() {                
    	List<Quarantine> quarantineList = null;
        
    	try {
            // load the Quarantine
            quarantineList = service.getAllQuarantine();
            
            if ( quarantineList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Quarantines" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Quarantines ", exc );
        	return null;
        }

        return quarantineList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Quarantine quarantine = null;
    protected QuarantineService service = null;
    private static final Logger LOGGER = Logger.getLogger(QuarantineQueryRestController.class.getName());
    
}
